# Cache for conditional imports and components
_CONDITIONAL_IMPORTS_CACHE: dict[str, tuple[Optional[Any], bool]] = {}
_DEFAULT_COMPONENTS_CACHE: Optional[List[Type[Any]]] = None


def _get_conditional_component(
    module_name: str, class_name: str, check_installation_setup: bool = False
) -> tuple[Optional[Any], bool]:
    """Lazily import a component and cache the result."""
    cache_key = f"{module_name}.{class_name}"
    if cache_key not in _CONDITIONAL_IMPORTS_CACHE:
        _CONDITIONAL_IMPORTS_CACHE[cache_key] = conditional_import(
            module_name, class_name, check_installation_setup
        )
    return _CONDITIONAL_IMPORTS_CACHE[cache_key]


def _build_default_components() -> List[Type[Any]]:
    """Build the list of default components, deferring conditional imports."""
    # Base components that are always available (no external dependencies)
    components: List[Type[Any]] = [
        # Classifiers
        FallbackClassifier,
        KeywordIntentClassifier,
        NLUCommandAdapter,
        LLMCommandGenerator,
        LLMBasedRouter,
        IntentBasedRouter,
        # Entity Extractors
        DucklingEntityExtractor,
        EntitySynonymMapper,
        RegexEntityExtractor,
        # Featurizers
        CountVectorsFeaturizer,
        RegexFeaturizer,
        # Tokenizers
        WhitespaceTokenizer,
        # Language Model Providers
        # Policies
        RulePolicy,
        MemoizationPolicy,
        AugmentedMemoizationPolicy,
        FlowPolicy,
        EnterpriseSearchPolicy,
        IntentlessPolicy,
    ]

    # Conditionally add components based on dependencies

    # components dependent on tensorflow
    DIETClassifier, DIET_CLASSIFIER_AVAILABLE = _get_conditional_component(
        "rasa.nlu.classifiers.diet_classifier",
        "DIETClassifier",
        check_installation_setup=True,
    )
    if DIET_CLASSIFIER_AVAILABLE:
        components.append(DIETClassifier)

    ConveRTFeaturizer, CONVERT_FEATURIZER_AVAILABLE = _get_conditional_component(
        "rasa.nlu.featurizers.dense_featurizer.convert_featurizer",
        "ConveRTFeaturizer",
        check_installation_setup=True,
    )
    if CONVERT_FEATURIZER_AVAILABLE:
        components.append(ConveRTFeaturizer)

    ResponseSelector, RESPONSE_SELECTOR_AVAILABLE = _get_conditional_component(
        "rasa.nlu.selectors.response_selector",
        "ResponseSelector",
        check_installation_setup=True,
    )
    if RESPONSE_SELECTOR_AVAILABLE:
        components.append(ResponseSelector)

    TEDPolicy, TED_POLICY_AVAILABLE = _get_conditional_component(
        "rasa.core.policies.ted_policy", "TEDPolicy", check_installation_setup=True
    )
    if TED_POLICY_AVAILABLE:
        components.append(TEDPolicy)

    UnexpecTEDIntentPolicy, UNEXPECTED_INTENT_POLICY_AVAILABLE = (
        _get_conditional_component(
            "rasa.core.policies.unexpected_intent_policy",
            "UnexpecTEDIntentPolicy",
            check_installation_setup=True,
        )
    )
    if UNEXPECTED_INTENT_POLICY_AVAILABLE:
        components.append(UnexpecTEDIntentPolicy)

    # components dependent on skops
    LogisticRegressionClassifier, LOGISTIC_REGRESSION_CLASSIFIER_AVAILABLE = (
        _get_conditional_component(
            "rasa.nlu.classifiers.logistic_regression_classifier",
            "LogisticRegressionClassifier",
        )
    )
    if LOGISTIC_REGRESSION_CLASSIFIER_AVAILABLE:
        components.append(LogisticRegressionClassifier)

    SklearnIntentClassifier, SKLEARN_INTENT_CLASSIFIER_AVAILABLE = (
        _get_conditional_component(
            "rasa.nlu.classifiers.sklearn_intent_classifier",
            "SklearnIntentClassifier",
        )
    )
    if SKLEARN_INTENT_CLASSIFIER_AVAILABLE:
        components.append(SklearnIntentClassifier)

    # components dependent on spacy
    LexicalSyntacticFeaturizer, LEXICAL_SYNTACTIC_FEATURIZER_AVAILABLE = (
        _get_conditional_component(
            "rasa.nlu.featurizers.sparse_featurizer.lexical_syntactic_featurizer",
            "LexicalSyntacticFeaturizer",
        )
    )
    if LEXICAL_SYNTACTIC_FEATURIZER_AVAILABLE:
        components.append(LexicalSyntacticFeaturizer)

    SpacyFeaturizer, SPACY_FEATURIZER_AVAILABLE = _get_conditional_component(
        "rasa.nlu.featurizers.dense_featurizer.spacy_featurizer", "SpacyFeaturizer"
    )
    if SPACY_FEATURIZER_AVAILABLE:
        components.append(SpacyFeaturizer)

    SpacyTokenizer, SPACY_TOKENIZER_AVAILABLE = _get_conditional_component(
        "rasa.nlu.tokenizers.spacy_tokenizer", "SpacyTokenizer"
    )
    if SPACY_TOKENIZER_AVAILABLE:
        components.append(SpacyTokenizer)

    SpacyEntityExtractor, SPACY_ENTITY_EXTRACTOR_AVAILABLE = _get_conditional_component(
        "rasa.nlu.extractors.spacy_entity_extractor", "SpacyEntityExtractor"
    )
    if SPACY_ENTITY_EXTRACTOR_AVAILABLE:
        components.append(SpacyEntityExtractor)

    SpacyNLP, SPACY_NLP_AVAILABLE = _get_conditional_component(
        "rasa.nlu.utils.spacy_utils", "SpacyNLP"
    )
    if SPACY_NLP_AVAILABLE:
        components.append(SpacyNLP)

    # components dependent on sklearn_crfsuite
    CRFEntityExtractor, CRF_ENTITY_EXTRACTOR_AVAILABLE = _get_conditional_component(
        "rasa.nlu.extractors.crf_entity_extractor", "CRFEntityExtractor"
    )
    if CRF_ENTITY_EXTRACTOR_AVAILABLE:
        components.append(CRFEntityExtractor)

    # components dependent on mitie
    MitieFeaturizer, MITIE_FEATURIZER_AVAILABLE = _get_conditional_component(
        "rasa.nlu.featurizers.dense_featurizer.mitie_featurizer", "MitieFeaturizer"
    )
    if MITIE_FEATURIZER_AVAILABLE:
        components.append(MitieFeaturizer)

    MitieTokenizer, MITIE_TOKENIZER_AVAILABLE = _get_conditional_component(
        "rasa.nlu.tokenizers.mitie_tokenizer", "MitieTokenizer"
    )
    if MITIE_TOKENIZER_AVAILABLE:
        components.append(MitieTokenizer)

    MitieIntentClassifier, MITIE_INTENT_CLASSIFIER_AVAILABLE = (
        _get_conditional_component(
            "rasa.nlu.classifiers.mitie_intent_classifier",
            "MitieIntentClassifier",
        )
    )
    if MITIE_INTENT_CLASSIFIER_AVAILABLE:
        components.append(MitieIntentClassifier)

    MitieEntityExtractor, MITIE_ENTITY_EXTRACTOR_AVAILABLE = _get_conditional_component(
        "rasa.nlu.extractors.mitie_entity_extractor", "MitieEntityExtractor"
    )
    if MITIE_ENTITY_EXTRACTOR_AVAILABLE:
        components.append(MitieEntityExtractor)

    MitieNLP, MITIE_NLP_AVAILABLE = _get_conditional_component(
        "rasa.nlu.utils.mitie_utils", "MitieNLP"
    )
    if MITIE_NLP_AVAILABLE:
        components.append(MitieNLP)

    # components dependent on jieba
    JiebaTokenizer, JIEBA_TOKENIZER_AVAILABLE = _get_conditional_component(
        "rasa.nlu.tokenizers.jieba_tokenizer", "JiebaTokenizer"
    )
    if JIEBA_TOKENIZER_AVAILABLE:
        components.append(JiebaTokenizer)

    return components


def __getattr__(name: str) -> Any:
    # Module-level __getattr__ (PEP 562) provides lazy loading for DEFAULT_COMPONENTS
    # and all _AVAILABLE flags, deferring the expensive conditional_import calls.
    if name == "DEFAULT_COMPONENTS":
        global _DEFAULT_COMPONENTS_CACHE
        if _DEFAULT_COMPONENTS_CACHE is None:
            _DEFAULT_COMPONENTS_CACHE = _build_default_components()
        return _DEFAULT_COMPONENTS_CACHE

    # Provide lazy loading for availability flags
    availability_map = {
        "TED_POLICY_AVAILABLE": ("rasa.core.policies.ted_policy", "TEDPolicy", True),
        "UNEXPECTED_INTENT_POLICY_AVAILABLE": (
            "rasa.core.policies.unexpected_intent_policy",
            "UnexpecTEDIntentPolicy",
            True,
        ),
        "DIET_CLASSIFIER_AVAILABLE": (
            "rasa.nlu.classifiers.diet_classifier",
            "DIETClassifier",
            True,
        ),
        "CONVERT_FEATURIZER_AVAILABLE": (
            "rasa.nlu.featurizers.dense_featurizer.convert_featurizer",
            "ConveRTFeaturizer",
            True,
        ),
        "RESPONSE_SELECTOR_AVAILABLE": (
            "rasa.nlu.selectors.response_selector",
            "ResponseSelector",
            True,
        ),
        "LOGISTIC_REGRESSION_CLASSIFIER_AVAILABLE": (
            "rasa.nlu.classifiers.logistic_regression_classifier",
            "LogisticRegressionClassifier",
            False,
        ),
        "SKLEARN_INTENT_CLASSIFIER_AVAILABLE": (
            "rasa.nlu.classifiers.sklearn_intent_classifier",
            "SklearnIntentClassifier",
            False,
        ),
        "LEXICAL_SYNTACTIC_FEATURIZER_AVAILABLE": (
            "rasa.nlu.featurizers.sparse_featurizer.lexical_syntactic_featurizer",
            "LexicalSyntacticFeaturizer",
            False,
        ),
        "SPACY_FEATURIZER_AVAILABLE": (
            "rasa.nlu.featurizers.dense_featurizer.spacy_featurizer",
            "SpacyFeaturizer",
            False,
        ),
        "SPACY_TOKENIZER_AVAILABLE": (
            "rasa.nlu.tokenizers.spacy_tokenizer",
            "SpacyTokenizer",
            False,
        ),
        "SPACY_ENTITY_EXTRACTOR_AVAILABLE": (
            "rasa.nlu.extractors.spacy_entity_extractor",
            "SpacyEntityExtractor",
            False,
        ),
        "SPACY_NLP_AVAILABLE": ("rasa.nlu.utils.spacy_utils", "SpacyNLP", False),
        "CRF_ENTITY_EXTRACTOR_AVAILABLE": (
            "rasa.nlu.extractors.crf_entity_extractor",
            "CRFEntityExtractor",
            False,
        ),
        "MITIE_FEATURIZER_AVAILABLE": (
            "rasa.nlu.featurizers.dense_featurizer.mitie_featurizer",
            "MitieFeaturizer",
            False,
        ),
        "MITIE_TOKENIZER_AVAILABLE": (
            "rasa.nlu.tokenizers.mitie_tokenizer",
            "MitieTokenizer",
            False,
        ),
        "MITIE_INTENT_CLASSIFIER_AVAILABLE": (
            "rasa.nlu.classifiers.mitie_intent_classifier",
            "MitieIntentClassifier",
            False,
        ),
        "MITIE_ENTITY_EXTRACTOR_AVAILABLE": (
            "rasa.nlu.extractors.mitie_entity_extractor",
            "MitieEntityExtractor",
            False,
        ),
        "MITIE_NLP_AVAILABLE": ("rasa.nlu.utils.mitie_utils", "MitieNLP", False),
        "JIEBA_TOKENIZER_AVAILABLE": (
            "rasa.nlu.tokenizers.jieba_tokenizer",
            "JiebaTokenizer",
            False,
        ),
    }

    if name in availability_map:
        module_name, class_name, check_setup = availability_map[name]
        _, available = _get_conditional_component(module_name, class_name, check_setup)
        return available

    raise AttributeError(f"module '{__name__}' has no attribute '{name}'")


if TYPE_CHECKING:
    # Provide typed stubs for names served via __getattr__ so mypy can type-check
    # callers that iterate or subscript these values.
    DEFAULT_COMPONENTS: List[Type[Any]]
